/*
 * prog18_caesar_cipher – reproduced from the obfuscated binary.
 *
 * The original program expects exactly two command‑line arguments:
 *   1. an integer shift value (optional leading '+' or '-')
 *   2. a text string to be Caesar‑ciphered.
 *
 * If the arguments are missing, the shift is not a valid integer,
 * or the text length exceeds 1024 characters, the program prints
 * the usage message:
 *
 *     USAGE
 *
 * (followed by a newline, because `puts` is used in the original).
 *
 * Otherwise the program prints the text with each alphabetic character
 * shifted by the given amount (modulo 26) and finally prints a newline.
 * Non‑alphabetic characters are copied unchanged.
 *
 * The shift is normalised to the range 0‑25, so both positive and
 * negative values work as expected.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_TEXT_LEN 1024

int main(int argc, char **argv)
{
    /* -----------------------------------------------------------------
     * Argument validation – the original binary checks for exactly three
     * arguments (program name + two user arguments).  If the check fails
     * it prints "USAGE" via puts().
     * ----------------------------------------------------------------- */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     * Parse the shift value.  The original code accepts an optional
     * leading '+' or '-' and then parses the decimal integer.  If the
     * string contains any non‑digit after the optional sign, the program
     * falls back to the usage message.
     * ----------------------------------------------------------------- */
    char *endptr;
    long raw_shift = strtol(argv[1], &endptr, 10);

    /* strtol stops at the first non‑digit; if we didn't consume the whole
       argument, it was not a valid integer. */
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }

    /* Normalise the shift to the range 0‑25 (the original does a
       modulo‑26 operation using a clever multiplication trick). */
    int shift = (int)raw_shift;
    shift %= 26;
    if (shift < 0)
        shift += 26;

    /* -----------------------------------------------------------------
     * Retrieve the text argument and enforce the length limit (0x400 = 1024).
     * The original binary prints USAGE if the length exceeds this limit.
     * ----------------------------------------------------------------- */
    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > MAX_TEXT_LEN) {
        puts("USAGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     * Perform the Caesar cipher.  Upper‑case and lower‑case letters are
     * shifted, other characters are emitted unchanged.  The original
     * implementation used a state‑machine with many magic constants;
     * the logic reduces to the classic formula:
     *
     *   ((c - base + shift) % 26) + base
     *
     * where base is 'A' for upper case and 'a' for lower case.
     * ----------------------------------------------------------------- */
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (unsigned char)((c - 'A' + shift) % 26 + 'A');
        } else if (c >= 'a' && c <= 'z') {
            c = (unsigned char)((c - 'a' + shift) % 26 + 'a');
        }
        putc(c, stdout);
    }

    /* The original program prints a final newline after processing the
       whole string. */
    putc('\n', stdout);
    return 0;
}
